function orientation(p,angle){const a=p.plate,origin=[Math.min(...a.outline.map(p=>p[0])),Math.min(...a.outline.map(p=>p[1]))],t=angle*Math.PI/180,c=Math.cos(t),s=Math.sin(t),raw=a.outline.map(q=>[c*(q[0]-origin[0])-s*(q[1]-origin[1]),s*(q[0]-origin[0])+c*(q[1]-origin[1])]),offset=[-Math.min(...raw.map(q=>q[0])),-Math.min(...raw.map(q=>q[1]))],poly=raw.map(q=>q.map((v,i)=>v+offset[i]));return {minX:origin[0],minY:origin[1],width:a.width,height:a.height,angle,transform:{c,s,offset},rotated:angle%180!==0,poly,w:Math.max(...poly.map(p=>p[0])),h:Math.max(...poly.map(p=>p[1]))};}
