export function verifyContourNesting(result,m){const ids=new Set;for(const s of result.sheets){const boxes=[];for(const p of s.parts){if(ids.has(p.part.id))throw Error('חלק כפול בקינון');ids.add(p.part.id);if(p.part.material!==s.material||p.part.plate.thickness!==s.thickness)throw Error('ערבוב חומר או עובי');if(p.transform&&(![p.transform.c,p.transform.s,...p.transform.offset].every(Number.isFinite)||Math.abs(p.transform.c*p.transform.c+p.transform.s*p.transform.s-1)>1e-7))throw Error('העתקה אינה סיבוב תקין');const poly=p.part.plate.outline.map(q=>mapContourPoint(p,q));validatePolygon(poly);const actual=bounds(poly);if(Math.abs(actual.x-p.x)>1e-4||Math.abs(actual.y-p.y)>1e-4||Math.abs(actual.r-actual.x-p.w)>1e-4||Math.abs(actual.t-actual.y-p.h)>1e-4)throw Error('נתוני מיקום ומעטפת אינם תואמים לקונטור');if(poly.some(q=>q[0]<m.margin-1e-4||q[1]<m.margin-1e-4||q[0]>s.width-m.margin+1e-4||q[1]>s.height-m.margin+1e-4))throw Error('חריגה מהלוח');boxes.push({poly,bounds:bounds(poly)});}for(let i=0;i<boxes.length;i++)for(let j=0;j<i;j++)if(!separated(boxes[i].bounds,boxes[j].bounds,m.gap)&&polygonConflict(boxes[i].poly,boxes[j].poly,m.gap))throw Error('פלטות חופפות או ללא מרווח נדרש');}if(ids.size+result.rejected.length!==result.total)throw Error('מלאי פלטות לא תואם');return true;}
